// Push gate: decides whether the agent may send a push to a user right now.
// Rules, checked in this order:
//   1. quiet hours, in the user's own time zone (start inclusive, end exclusive)
//   2. daily cap, counted per calendar day in the user's own time zone
// A blocked attempt is not recorded. An allowed attempt is recorded as sent.

const HISTORY_MS = 72 * 3600 * 1000; // longer than any local day, in any zone
const SWEEP_EVERY_MS = 3600 * 1000;

const formatters = new Map();

function formatterFor(timeZone) {
  let f = formatters.get(timeZone);
  if (!f) {
    f = new Intl.DateTimeFormat('en-CA', {
      timeZone,
      hourCycle: 'h23',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    });
    formatters.set(timeZone, f);
  }
  return f;
}

// Returns { day: "YYYY-MM-DD", minutes: minutes since local midnight }.
function localParts(ms, timeZone) {
  const p = {};
  for (const { type, value } of formatterFor(timeZone).formatToParts(ms)) p[type] = value;
  return {
    day: `${p.year}-${p.month}-${p.day}`,
    minutes: Number(p.hour) * 60 + Number(p.minute),
  };
}

function parseClock(s) {
  const m = typeof s === 'string' ? /^([01]\d|2[0-3]):([0-5]\d)$/.exec(s) : null;
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
}

function inQuietHours(minutes, start, end) {
  if (start === end) return false; // no quiet period configured
  return start < end
    ? minutes >= start && minutes < end
    : minutes >= start || minutes < end; // runs past midnight
}

const deny = (reason) => ({ allowed: false, reason });

export function createPushGate() {
  const sent = new Map(); // user id -> array of send times (ms)
  let lastSweep = -Infinity;

  function sweep(nowMs) {
    if (nowMs - lastSweep < SWEEP_EVERY_MS) return;
    lastSweep = nowMs;
    for (const [id, times] of sent) {
      const kept = times.filter((t) => t > nowMs - HISTORY_MS);
      if (kept.length) sent.set(id, kept);
      else sent.delete(id);
    }
  }

  return {
    attempt(user, now) {
      const nowMs = now instanceof Date ? now.getTime() : NaN;
      if (!Number.isFinite(nowMs)) return deny('invalid_time');

      if (!user || typeof user !== 'object' || user.id == null || user.id === '') {
        return deny('invalid_user_settings');
      }
      const start = parseClock(user.quietStart);
      const end = parseClock(user.quietEnd);
      const cap = user.dailyCap;
      if (start === null || end === null || !Number.isInteger(cap) || cap < 0) {
        return deny('invalid_user_settings');
      }
      let here;
      try {
        here = localParts(nowMs, user.timeZone);
      } catch {
        return deny('invalid_user_settings');
      }

      if (inQuietHours(here.minutes, start, end)) return deny('quiet_hours');

      sweep(nowMs);
      const times = sent.get(user.id) ?? [];
      // Re-derive each past push's local day in the zone passed now, so a
      // user who changes zone is still counted by the day they are living.
      let today = 0;
      for (const t of times) {
        if (localParts(t, user.timeZone).day === here.day) today++;
      }
      if (today >= cap) return deny('daily_cap_reached');

      times.push(nowMs);
      sent.set(user.id, times);
      return { allowed: true, reason: null };
    },
  };
}

import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-sonnet/work/courier-g2-3/bot.mjs';

const tokyo = { id: 'u1', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
const at = (s) => new Date(s);
let g = createPushGate();

// Tokyo = UTC+9. 12:00 UTC = 21:00 JST allowed; 13:00 UTC = 22:00 JST quiet.
assert.deepEqual(g.attempt(tokyo, at('2026-10-23T12:00:00Z')), { allowed: true, reason: null });
assert.equal(g.attempt(tokyo, at('2026-10-23T13:00:00Z')).reason, 'quiet_hours');
assert.equal(g.attempt(tokyo, at('2026-10-23T21:59:00Z')).reason, 'quiet_hours'); // 06:59 JST
assert.equal(g.attempt(tokyo, at('2026-10-23T22:00:00Z')).allowed, true); // 07:00 JST, end exclusive

// Cap: 3 per local day; quiet-blocked attempts did not count (2 sent so far today JST 10-24).
assert.equal(g.attempt(tokyo, at('2026-10-23T23:00:00Z')).allowed, true); // 08:00 JST -> 3rd on 10-24? no: 2nd
assert.equal(g.attempt(tokyo, at('2026-10-23T23:30:00Z')).allowed, true); // 3rd
assert.equal(g.attempt(tokyo, at('2026-10-23T23:45:00Z')).reason, 'daily_cap_reached');
// Local midnight rolls the day (UTC date is irrelevant): 21:00 JST same day is quiet-free, still capped.
assert.equal(g.attempt(tokyo, at('2026-10-24T11:00:00Z')).reason, 'daily_cap_reached'); // 20:00 JST 10-24
assert.equal(g.attempt(tokyo, at('2026-10-24T15:30:00Z')).reason, 'quiet_hours');
assert.equal(g.attempt(tokyo, at('2026-10-24T22:00:00Z')).allowed, true); // 10-25 07:00 JST, new day

// Same-day window (no midnight wrap) and the gates are independent.
const day = { id: 'u2', timeZone: 'America/New_York', quietStart: '13:00', quietEnd: '15:00', dailyCap: 1 };
const g2 = createPushGate();
assert.equal(g2.attempt(day, at('2026-10-23T17:30:00Z')).reason, 'quiet_hours'); // 13:30 EDT
assert.equal(g2.attempt(day, at('2026-10-23T14:00:00Z')).allowed, true);
assert.equal(g.attempt({ ...day, id: 'u2' }, at('2026-10-23T14:00:00Z')).allowed, true);
assert.equal(g2.attempt(day, at('2026-10-23T20:00:00Z')).reason, 'daily_cap_reached');
// DST end in New York 2026-11-01: day has 25h; 23:30 EST on 10-31 is still a different day than 11-01.
assert.equal(g2.attempt(day, at('2026-11-01T17:00:00Z')).allowed, true);

// Cap 0, settings from the current call, bad input.
assert.equal(createPushGate().attempt({ ...tokyo, dailyCap: 0 }, at('2026-10-23T12:00:00Z')).reason, 'daily_cap_reached');
const g3 = createPushGate();
assert.equal(g3.attempt({ ...tokyo, dailyCap: 1 }, at('2026-10-23T03:00:00Z')).allowed, true);
assert.equal(g3.attempt({ ...tokyo, dailyCap: 2 }, at('2026-10-23T04:00:00Z')).allowed, true);
assert.equal(g3.attempt({ ...tokyo, timeZone: 'Nope/Zone' }, at('2026-10-23T04:00:00Z')).reason, 'invalid_user_settings');
assert.equal(g3.attempt({ ...tokyo, quietStart: '25:00' }, at('2026-10-23T04:00:00Z')).reason, 'invalid_user_settings');
assert.equal(g3.attempt(tokyo, new Date('x')).reason, 'invalid_time');
// Midnight edge: 00:00 local must format as 00 not 24.
assert.equal(createPushGate().attempt({ ...tokyo, quietStart: '00:00', quietEnd: '00:30' }, at('2026-10-23T15:00:00Z')).reason, 'quiet_hours');
console.log('ok');
